        x, y = pos
        for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
            new_pos = [x+dx, y+dy]
            if is_valid(new_pos):
                yield new_pos

    def closest(targets):
        min_dist = float('inf')
        target_pos = None
        for t in targets:
            dist = abs(t[0] - agent_pos[0]) + abs(t[1] - agent_pos[1])
            if dist < min_dist:
                min_dist = dist
                target_pos = t
        return target_pos

